package hp.common.security;
import org.junit.Test;import static org.junit.Assert.*;import org.springframework.mock.web.*;import javax.servlet.*;import java.util.*;
public class NativeSecurityTest {
 @Test public void passwordSaltAndVerification()throws Exception{String a=PasswordHash.hash("GoodPassword123!"),b=PasswordHash.hash("GoodPassword123!");assertNotEquals(a,b);assertTrue(PasswordHash.verify("GoodPassword123!",a));assertFalse(PasswordHash.verify("wrong",a));assertFalse(PasswordHash.verify("GoodPassword123!","legacy-md5"));}
 @Test public void identityIgnoresForgedFields(){MockHttpSession s=new MockHttpSession();s.setAttribute("ID","owner");s.setAttribute("IDX",1);Map<String,Object> m=new HashMap<String,Object>();m.put("ID","victim");m.put("IDX",9);SessionIdentity.bind(m,s);assertEquals("owner",m.get("ID"));assertEquals(1,m.get("IDX"));}
 @Test public void csrfRoleAndMethods()throws Exception{RequestSecurityFilter f=new RequestSecurityFilter();MockHttpServletRequest r=new MockHttpServletRequest("GET","/hospital/admin/list");r.setContextPath("/hospital");MockHttpServletResponse w=new MockHttpServletResponse();f.doFilter(r,w,new MockFilterChain());assertEquals(401,w.getStatus());r.getSession().setAttribute("ID","member");w=new MockHttpServletResponse();f.doFilter(r,w,new MockFilterChain());assertEquals(403,w.getStatus());r.setRequestURI("/hospital/mypage/InsertFav");w=new MockHttpServletResponse();f.doFilter(r,w,new MockFilterChain());assertEquals(405,w.getStatus());r.setMethod("POST");w=new MockHttpServletResponse();f.doFilter(r,w,new MockFilterChain());assertEquals(403,w.getStatus());r.addHeader("X-CSRF-Token",r.getSession().getAttribute("CSRF"));w=new MockHttpServletResponse();MockFilterChain chain=new MockFilterChain();f.doFilter(r,w,chain);assertNotNull(chain.getRequest());}
}
